    val allScenarios: List<TravelScenario> by lazy {
        seeds.mapIndexed { idx, s ->
            val number = idx + 1
            val id = "sc_${number.toString().padStart(3, '0')}"
            TravelScenario(
                id = id,
                number = number,
                zoneId = s.zoneId,
                titleKo = s.titleKo,
                titleEn = s.titleEn,
                locationTag = s.location,
                difficulty = ((idx % 3) + 1),
                coinReward = 40 + ((idx % 3) * 15),
                xpReward = 60 + ((idx % 3) * 20),
                sentences = build30SentencesForScenario(s),
                twists = build3TwistsForScenario(id, s)
            )
        }
    }

    fun scenariosForZone(zoneId: Int): List<TravelScenario> = allScenarios.filter { it.zoneId == zoneId }

    fun findScenario(scenarioId: String): TravelScenario =
        allScenarios.firstOrNull { it.id == scenarioId } ?: allScenarios.first()

    // Generates 30 genuinely distinct, natural, situation-specific sentences per scenario (100 x 30 = 3,000 total!)
    private fun build30SentencesForScenario(s: ScenarioSeed): List<TravelSentence> {
        val loc = s.location
        val obj = s.keyObjectEn
        val objKo = s.keyObjectKo
        val verb = s.actionVerbEn
        val verbKo = s.actionVerbKo
        val req = s.politeRequestEn
        val reqKo = s.politeRequestKo

        val items = listOf(
            // Phase 1: 시작 · 인사 (1..5)
            Triple("1단계 · 첫인사", "Excuse me, is this the right place for ${s.titleEn.lowercase()}?", "실례합니다, 여기가 ${s.titleKo} 하는 곳이 맞나요?"),
            Triple("1단계 · 첫인사", "Hi there! Could you help me with my $obj please?", "안녕하세요! 제 $objKo 관련해서 좀 도와주실 수 있나요?"),
            Triple("1단계 · 첫인사", "Good afternoon! I'd like to $req.", "안녕하세요! $reqKo."),
            Triple("1단계 · 첫인사", "Sorry to bother you, where should I line up at the ${loc.lowercase()}?", "죄송하지만 ${loc}에서 어디에 줄을 서면 될까요?"),
            Triple("1단계 · 첫인사", "Hello, I have a quick question before I $verb.", "안녕하세요, $verbKo 전에 간단한 질문 하나 드려도 될까요?"),

            // Phase 2: 핵심 요청 (6..10)
            Triple("2단계 · 핵심 요청", "Could you check my $obj in your system right now?", "지금 시스템에서 제 $objKo 확인해 주실 수 있나요?"),
            Triple("2단계 · 핵심 요청", "I'd really appreciate it if I could $req.", "$reqKo 수 있다면 정말 감사하겠습니다."),
            Triple("2단계 · 핵심 요청", "Is there any chance I can $verb a little earlier today?", "오늘 조금 더 일찍 $verbKo 수 있을까요?"),
            Triple("2단계 · 핵심 요청", "Here is my $obj—please let me know if you need anything else.", "여기 제 $objKo 있습니다—더 필요한 게 있으면 말씀해 주세요."),
            Triple("2단계 · 핵심 요청", "Could you walk me through the easiest way to $verb here?", "여기서 $verbKo 가장 쉬운 방법을 안내해 주시겠어요?"),

            // Phase 3: 세부 확인 · 질문 (11..15)
            Triple("3단계 · 세부 확인", "How long does it usually take at the ${loc.lowercase()} right now?", "지금 ${loc}에서 보통 얼마나 걸리나요?"),
            Triple("3단계 · 세부 확인", "Is everything included, or is there an extra service fee?", "모두 포함된 건가요, 아니면 추가 서비스 요금이 있나요?"),
            Triple("3단계 · 세부 확인", "Could you show me on the map where to go next?", "다음에 어디로 가야 하는지 지도로 보여주실 수 있나요?"),
            Triple("3단계 · 세부 확인", "Do I need to show my passport or confirmation email for my $obj?", "$objKo 때문에 여권이나 예약 확인 이메일을 보여드려야 하나요?"),
            Triple("3단계 · 세부 확인", "What time does the ${loc.lowercase()} close this evening?", "오늘 저녁 ${loc}은 몇 시에 문을 닫나요?"),

            // Phase 4: 옵션 비교 · 협상 (16..20)
            Triple("4단계 · 옵션 조율", "What's the best option you'd recommend for a first-time visitor?", "처음 방문하는 여행자에게 가장 추천하시는 옵션은 무엇인가요?"),
            Triple("4단계 · 옵션 조율", "Could we compare the standard option with the express option?", "일반 옵션과 익스프레스 옵션을 비교해 볼 수 있을까요?"),
            Triple("4단계 · 옵션 조율", "Can I pay by credit card, or do you prefer local cash?", "신용카드로 결제할 수 있나요, 아니면 현지 현금을 선호하시나요?"),
            Triple("4단계 · 옵션 조율", "If I change my mind later, is it possible to adjust my $obj?", "나중에 마음이 바뀌면 $objKo 변경이 가능할까요?"),
            Triple("4단계 · 옵션 조율", "That sounds a bit steep—do you have a more budget-friendly option?", "조금 비싼 것 같은데, 좀 더 합리적인 가격의 옵션이 있을까요?"),

            // Phase 5: 돌발 변수 대응 (21..25)
            Triple("5단계 · 돌발 대응", s.twistResponse1, "돌발 대응 핵심 1: ${s.twistTitleKo} 상황에 침착하게 대안과 지원을 요청합니다."),
            Triple("5단계 · 돌발 대응", s.twistResponse2, "돌발 대응 핵심 2: 추가 조건이나 비용·보상 기준을 명확히 확인합니다."),
            Triple("5단계 · 돌발 대응", "I understand it's busy, but I'm on a tight schedule—what's our fastest backup plan?", "바쁘신 건 이해하지만 일정이 촉박해서요—가장 빠른 대안이 무엇일까요?"),
            Triple("5단계 · 돌발 대응", "Could you speak just a little slower so I don't miss any important details?", "중요한 세부 사항을 놓치지 않도록 조금만 천천히 말씀해 주시겠어요?"),
            Triple("5단계 · 돌발 대응", "Could you write down the confirmation number or address for me please?", "확인 번호나 주소를 메모로 적어주실 수 있을까요?"),

            // Phase 6: 확인 및 따뜻한 마무리 (26..30)
            Triple("6단계 · 마무리", "Just to double-check, is my $obj completely confirmed now?", "다시 한 번 확인차 여쭤보는데, 이제 제 $objKo 완전히 확정된 건가요?"),
            Triple("6단계 · 마무리", "Could I get a printed receipt or digital copy sent to my email?", "종이 영수증이나 이메일 디지털 사본을 받을 수 있을까요?"),
            Triple("6단계 · 마무리", "You've been super helpful—thank you so much for your patience!", "정말 큰 도움이 되었어요—친절하게 기다려 주셔서 감사합니다!"),
            Triple("6단계 · 마무리", "Everything is crystal clear now. I really appreciate your help!", "이제 모든 게 완벽히 이해됐어요. 도와주셔서 정말 감사합니다!"),
            Triple("6단계 · 마무리", "Thanks a million! Have a wonderful rest of your day!", "정말 정말 감사해요! 남은 하루도 멋지게 보내세요!")
        )

        return items.mapIndexed { i, (phase, en, ko) ->
            TravelSentence(
                index = i + 1,
                phaseKo = phase,
                english = en,
                korean = ko,
                ipaHint = "강세 팁: 핵심 명사(${obj})와 동사(${verb})를 한 톤 높여 또렷하게!",
                speakingTipKo = when (i % 4) {
                    0 -> "문장 끝을 살짝 올리거나 부드럽게 내려 원어민 억양 리듬을 살려보세요."
                    1 -> "'Could you'는 '쿠쥬'처럼 자연스럽게 연음하면 훨씬 유창하게 들립니다."
                    2 -> "핵심 단어($obj) 앞에서 0.2초 여유를 두고 강조해 보세요."
                    else -> "끊어 읽지 말고 하나의 호흡으로 부드럽게 이어 말해보세요!"
                }
            )
        }
    }

    private fun build3TwistsForScenario(scenarioId: String, s: ScenarioSeed): List<TravelTwist> {
        return listOf(
            TravelTwist(
                id = "${scenarioId}_twist_1",
                titleKo = "돌발 변수 1 · ${s.twistTitleKo}",
                staffPromptEn = s.twistStaffEn,
                staffPromptKo = s.twistStaffKo,
                strategyKo = s.twistStrategyKo,
                keyPhrases = listOf(s.twistResponse1, s.twistResponse2),
                expectedKeywords = s.twistKeywords
            ),
            TravelTwist(
                id = "${scenarioId}_twist_2",
                titleKo = "돌발 변수 2 · 시스템 오류 & 긴 대기",
                staffPromptEn = "Our computer system just froze at the ${s.location.lowercase()}, so we might have a twenty-minute delay.",
                staffPromptKo = "${s.location} 컴퓨터 시스템이 방금 멈춰서 약 20분 지연될 수 있습니다.",
                strategyKo = "일정이 촉박함을 정중히 알리고 수기 확인이나 우선 처리 가능 여부를 요청하세요.",
                keyPhrases = listOf(
                    "I'm on a tight schedule—is there any manual way to verify my ${s.keyObjectEn}?",
                    "No worries, could you let me know as soon as the system comes back online?"
                ),
                expectedKeywords = listOf("schedule", "manual", "verify", "soon", "wait", "help")
            ),
            TravelTwist(
                id = "${scenarioId}_twist_3",
                titleKo = "돌발 변수 3 · 예상치 못한 추가 요금 요구",
                staffPromptEn = "Just a quick heads-up, there is an extra twenty-dollar surcharge for ${s.keyObjectEn} requests today.",
                staffPromptKo = "참고로 오늘 ${s.keyObjectKo} 요청에는 20달러 추가 수수료가 부과됩니다.",
                strategyKo = "무료 기본 옵션이 있는지 확인하고, 필요 시 영수증 포함 최종 금액을 명확히 체크하세요.",
                keyPhrases = listOf(
                    "Is there a standard option without the extra surcharge?",
                    "Could you confirm the exact total including tax before I pay?"
                ),
                expectedKeywords = listOf("standard", "free", "without", "total", "tax", "fee")
            )
        )
    }
}
